SELECT CASE WHEN c.age >= 59 THEN 'high' WHEN c.age >= 42 THEN 'mid' ELSE 'low' END AS age_bucket, SUM(CASE WHEN o.channel = 'web' THEN o.shipping_fee ELSE 0 END) AS web_shipping_fee FROM orders o JOIN stores s ON o.store_id = s.id JOIN customers c ON o.customer_id = c.id GROUP BY CASE WHEN c.age >= 59 THEN 'high' WHEN c.age >= 42 THEN 'mid' ELSE 'low' END HAVING SUM(CASE WHEN o.channel = 'web' THEN o.shipping_fee ELSE 0 END) >= 38 ORDER BY web_shipping_fee DESC, age_bucket
